import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import type { Comment, Post } from '@/types/blog'

export const revalidate = 300

type BlogPostPageProps = {
  params: Promise<{ id: string }>
}

async function getPostData(
  id: string
): Promise<{ post: Post; comments: Comment[] } | null> {
  try {
    const [postRes, commentsRes] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }),
    ])

    if (!postRes.ok) {
      return null
    }

    const post = (await postRes.json()) as Post
    const comments = (await commentsRes.json()) as Comment[]

    if (!post.id) {
      return null
    }

    return { post, comments }
  } catch {
    return null
  }
}

export async function generateStaticParams() {
  const posts = (await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())) as Post[]

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const data = await getPostData(id)

  if (!data) {
    return { title: 'Post Not Found' }
  }

  const description = data.post.body.substring(0, 160)

  return {
    title: data.post.title,
    description,
    openGraph: {
      title: data.post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const data = await getPostData(id)

  if (!data) {
    notFound()
  }

  const { post, comments } = data

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

